public static String enchant(int power) {
    return "Generic enchantment: " + power;
}
public static String enchant(int power, String element) {
    return element + " enchantment: " + power;
}
// enchant(5)           → "Generic enchantment: 5"
// enchant(5, "Fire")   → "Fire enchantment: 5"

// Deep nesting — hard to read
public static void castSpell(String name, int mana) {
    if (name != null) {
        if (mana > 0) {
            System.out.println("Casting " + name);
        }
    }
}
// Guard clauses — clean
public static void castSpell(String name, int mana) {
    if (name == null) return;
    if (mana <= 0) return;
    System.out.println("Casting " + name);
}

